from lib import *
L = lambda *a, **k: lesson(34, "A0", *a, **k)
V = "verb"
A = "adjective"
L(1, "Телефон", "Говорити про дзвінки й повідомлення.",
 "A message — повідомлення. A text — коротке повідомлення на телефон; це ще й дієслово: Text me — «напишіть мені». Send — надсилати. Answer ви знаєте як «відповідь»; answer the phone — «взяти слухавку». My battery is low — «батарея сідає».",
 [W("message", "/ˈmesɪdʒ/", "noun", "повідомлення", "I have a message.", "У мене є повідомлення."),
  W("text", "/tekst/", V, "писати повідомлення", "Text me later.", "Напишіть мені пізніше."),
  W("send", "/send/", V, "надсилати", "Send me a message.", "Надішліть мені повідомлення."),
  W("answer", "/ˈɑːnsə/", V, "відповідати", "He doesn't answer the phone.", "Він не бере слухавку."),
  W("battery", "/ˈbætri/", "noun", "батарея", "My battery is low.", "У мене сідає батарея."),
  W("low", "/ləʊ/", A, "низький", "Low battery.", "Низький заряд.")],
 [li("How often do I take the tablets?", "Повторимо. Двічі на день. Що відповість аптекар?", ["Twice a day.", "Two a day.", "Second day."], "Twice a day."),
  mt([("message", "повідомлення"), ("text", "писати повідомлення"), ("send", "надсилати"), ("answer", "відповідати"), ("battery", "батарея"), ("low", "низький")], "Слова про телефон."),
  liu("Send me a message.", "Прослухайте. Про що просить людина?", ["Надіслати їй повідомлення", "Зателефонувати їй", "Дати їй телефон"], "Send me a message."),
  liu("She doesn't answer the phone.", "Прослухайте. Що відбувається?", ["Вона не бере слухавку", "У неї немає телефона", "Вона телефонує"], "Doesn't answer the phone."),
  liu("My battery is low. Do you have a charger?", "Прослухайте. Що потрібно людині?", ["Зарядка", "Новий телефон", "Номер телефону"], "A charger."),
  fb("___ me a message, please.", ["Send", "Answer", "Speak"], "Send me a message."),
  fb("He doesn't ___ the phone.", ["answer", "send", "text"], "Answer the phone."),
  fb("My battery is ___. I need a charger.", ["low", "slow", "late"], "Low battery."),
  mc("Як сказати «Напишіть мені»?", ["Text me.", "Text to me it.", "Message me to."], "Text me."),
  bs("Надішліть мені повідомлення.", ["Send", "me", "a", "message"], ["text", "I"], "Send me a message."),
  tr("У мене сідає батарея.", ["My battery is low"], "My battery is low."),
  li("Can you call me tomorrow?", "Ви згодні, але краще напишете. Що відповісти?", ["Sure. I can text you.", "Sure. I can text to you it.", "Sure. I answer battery."], "Sure. I can text you.")])
