  W("soon", "/suːn/", "adverb", "скоро", "See you soon.", "До скорої зустрічі."),
  W("sounds good", "/ˌsaʊndz ˈɡʊd/", "phrase", "звучить добре, згода", "Sounds good!", "Згода!"),
  W("no worries", "/ˌnəʊ ˈwʌriz/", "phrase", "нічого страшного", "No worries.", "Нічого страшного."),
