  mt([("on my way", "уже їду"), ("soon", "скоро"), ("sounds good", "згода"), ("no worries", "нічого страшного"), ("reply", "відписати")], "Мова коротких повідомлень."),
  liu("I'm on my way. See you soon!", "Прослухайте. Що пише людина?", ["Вона вже їде й скоро буде", "Вона ще вдома", "Вона не приїде"], "On my way, see you soon."),
  liu("Sorry, I'm late. — No worries.", "Прослухайте. Як відповіли на вибачення?", ["Нічого страшного", "Це погано", "Не приходьте"], "No worries."),
  liu("Let's meet at seven. — Sounds good!", "Прослухайте. Чи згодна друга людина?", ["Так", "Ні", "Вона не впевнена"], "Sounds good — згода."),
  mc("Вам пишуть: Sorry, I can't come today. Що відповісти по-дружньому?", ["No worries. See you soon!", "No worry you. See soon!", "Sounds bad wrong."], "No worries. See you soon!"),
